window.ScripturaLexicons.BDAG_PART_0265 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-01\" data-source=\"BDAG\" data-search=\"παιδίον, ου, τό substantivo neutro criança; bebê; filho querido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παιδίον, ου, τό</td><td>substantivo neutro</td><td>criança; bebê; filho querido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-02\" data-source=\"BDAG\" data-search=\"παιδίσκη, ης, ἡ substantivo feminino escrava; serva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παιδίσκη, ης, ἡ</td><td>substantivo feminino</td><td>escrava; serva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-03\" data-source=\"BDAG\" data-search=\"παιδόθεν advérbio desde a infância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παιδόθεν</td><td>advérbio</td><td>desde a infância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-04\" data-source=\"BDAG\" data-search=\"παιδοφθορέω verbo atividade sexual com rapaz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παιδοφθορέω</td><td>verbo</td><td>atividade sexual com rapaz</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-05\" data-source=\"BDAG\" data-search=\"παιδοφθόρος, ου, ὁ substantivo masculino pederasta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παιδοφθόρος, ου, ὁ</td><td>substantivo masculino</td><td>pederasta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-06\" data-source=\"BDAG\" data-search=\"παίζω verbo brincar; divertir-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παίζω</td><td>verbo</td><td>brincar; divertir-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-07\" data-source=\"BDAG\" data-search=\"παῖς, παιδός, ὁ substantivo masculino/feminino menino; filho; servo; Filho/Servo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παῖς, παιδός, ὁ</td><td>substantivo masculino/feminino</td><td>menino; filho; servo; Filho/Servo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-08\" data-source=\"BDAG\" data-search=\"παίω verbo golpear; ferir; picar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παίω</td><td>verbo</td><td>golpear; ferir; picar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-09\" data-source=\"BDAG\" data-search=\"Πακατιανός, ή, όν adjetivo gentílico pacatiano; da Pacácia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πακατιανός, ή, όν</td><td>adjetivo gentílico</td><td>pacatiano; da Pacácia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-10\" data-source=\"BDAG\" data-search=\"πάλαι advérbio outrora; há muito; já BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάλαι</td><td>advérbio</td><td>outrora; há muito; já</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-11\" data-source=\"BDAG\" data-search=\"παλαιός, ά, όν adjetivo antigo; velho; obsoleto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παλαιός, ά, όν</td><td>adjetivo</td><td>antigo; velho; obsoleto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-12\" data-source=\"BDAG\" data-search=\"παλαιότης, ητος, ἡ substantivo feminino antiguidade; obsolescência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παλαιότης, ητος, ἡ</td><td>substantivo feminino</td><td>antiguidade; obsolescência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-13\" data-source=\"BDAG\" data-search=\"παλαιόω verbo envelhecer; tornar obsoleto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παλαιόω</td><td>verbo</td><td>envelhecer; tornar obsoleto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-14\" data-source=\"BDAG\" data-search=\"παλαίω verbo lutar corpo a corpo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παλαίω</td><td>verbo</td><td>lutar corpo a corpo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-15\" data-source=\"BDAG\" data-search=\"πάλη, ης, ἡ substantivo feminino luta; combate BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάλη, ης, ἡ</td><td>substantivo feminino</td><td>luta; combate</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-16\" data-source=\"BDAG\" data-search=\"παλιγγενεσία, ας, ἡ substantivo feminino renovação; regeneração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παλιγγενεσία, ας, ἡ</td><td>substantivo feminino</td><td>renovação; regeneração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-17\" data-source=\"BDAG\" data-search=\"πάλιν advérbio de volta; novamente; por outro lado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάλιν</td><td>advérbio</td><td>de volta; novamente; por outro lado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-18\" data-source=\"BDAG\" data-search=\"παλινγενεσία remissão ver παλιγγενεσία BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παλινγενεσία</td><td>remissão</td><td>ver παλιγγενεσία</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-19\" data-source=\"BDAG\" data-search=\"παλίουρος substantivo masculino/feminino sarça; matagal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παλίουρος</td><td>substantivo masculino/feminino</td><td>sarça; matagal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0265-20\" data-source=\"BDAG\" data-search=\"παμβότανον, ου, τό substantivo neutro vegetação que cobre tudo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παμβότανον, ου, τό</td><td>substantivo neutro</td><td>vegetação que cobre tudo</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0265-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παιδίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παιδίον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hdt., Aristoph. e posteriores), diminutivo de <span class=\"greek\">παῖς</span> (Reader, Polemo 274, com referência a Hippocr., Sept. 5 e Philo, Op. 105: criança muito pequena, «até os sete anos»; B-D-F §111, 3; Mlt.-H. 345).<br>\n① Criança normalmente abaixo da idade da puberdade, criança.<br>\nⓐ Criança muito pequena, bebê, aplicado a meninos e meninas. Acerca de um recém-nascido (Diod S 4, 20, 3; Just., D. 34, 2 e outros [segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:8f</a>]; Tat. 33, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:21</a>, variante textual (oito dias de idade, como em Gen 17:12); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:21</a>. Os bebês são alimentados com mel e depois leite, B 6:17 (cf. Diod S 5, 70, 3 <span class=\"greek\">αὗται</span> [<span class=\"greek\">αἱ</span> <span class=\"greek\">Νύμφαι</span>] <span class=\"greek\">δὲ</span> <span class=\"greek\">μέλι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γάλα</span> <span class=\"greek\">μίσγουσαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">παιδίον</span> [<span class=\"greek\">τὸν</span> <span class=\"greek\">Δία</span>] <span class=\"greek\">ἔθρεψαν</span>.—HUsener [em <span class=\"greek\">γάλα</span> b]). Os que nascem de novo têm <span class=\"greek\">ὡς</span> <span class=\"greek\">παιδίων</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>, «alma como a das crianças recém-nascidas», B 6:11.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:8</a>, 9, 11, 13f, 20f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:59</a>, 66, 76, 80; 2:17, 27, 40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:23</a> (cf. Ex 2:2f). GJs 20:3f; 21:3; 22:1, variante textual (em vez de <span class=\"greek\">βρέφος</span>); 22:2, variante textual (em vez de <span class=\"greek\">παῖς</span>).<br>\nⓑ Com referência à idade (ApcEsdr 4:33, 35 p. 29, 9 e 12 Tdf. <span class=\"greek\">παιδίον</span> … <span class=\"greek\">γέρων</span>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:2</a>, 4f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:36f</a>; 10:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:47f</a>; 18:17; 1 Cl 16:3 (Is 53:2). No plural, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:16</a>; 19:13f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:28</a>; 10:13f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:32</a>; 18:16 (sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:14</a>, 15 e paralelos, ver JBlinzler, Klerusblatt ’44, 90–96). <span class=\"greek\">γυναῖκες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παιδία</span>, «mulheres e crianças» (Num 14:3; Jdth 7:23; 4 Macc 4:9; cf. Jos., Bell. 4, 115), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:21</a>; 15:38. <span class=\"greek\">παιδία</span> … <span class=\"greek\">πατέρες</span> … <span class=\"greek\">νεανίσκοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:14</a>.—B 8:1ab. Sobre meninas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:39</a>–41; 7:30.<br>\nⓒ Com referência a parentesco; o pai é indicado pelo genitivo (<span class=\"greek\">μου</span>, como TestJob 39:12; cf. Epict. 4, 1, 141 <span class=\"greek\">σου</span>; TestJob 4:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.49\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:49</a>. No plural, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:7</a>. A criança é indicada pelo genitivo na expressão com «pai»: <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παιδίου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:24</a>.<br>\n② Pessoa receptiva à instrução, criança, extensão figurada da acepção 1: <span class=\"greek\">παιδία</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">φρεσίν</span>, «Crianças quanto ao entendimento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:20</a>.—Com referência à atitude das crianças perante a verdade (Artem. 2, 69 p. 162, 7: <span class=\"greek\">τὰ</span> <span class=\"greek\">παιδία</span> <span class=\"greek\">ἀληθῆ</span> <span class=\"greek\">λέγει</span>· <span class=\"greek\">οὐδέπω</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">οἶδε</span> <span class=\"greek\">ψεύδεσθαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐξαπατᾶν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:3</a>.<br>\n③ Pessoa estimada como os pais estimam o filho, criança, extensão figurada da acepção 1.<br>\nⓐ Sobre os filhos de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:13f</a> (v. 13 segundo Is 8:18, mas entendido em sentido neotestamentário).<br>\nⓑ Como forma familiar de tratamento empregada por pessoa respeitada que se considera em relação de intimidade paternal com seus interlocutores (Cornutus 1 p. 1, 1 <span class=\"greek\">ὦ</span> <span class=\"greek\">π</span>.; Athen. 13, 47, 584c), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:18</a>; 3:7, variante textual. Empregado pelo Cristo ressuscitado ao dirigir-se aos discípulos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:5</a>.—B. 92. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παιδίσκη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παιδίσκη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span>, diminutivo de <span class=\"greek\">παῖς</span>, «menina»; em nossa literatura, sempre aplicado à classe servil, escrava, serva (assim em Hdt. e posteriores; papiros [também Dssm. LO 167, 6 = LAE 200, 18; outros exemplos em New Docs 2, 87f], LXX, TestAbr A; TestJob 21:2; Test12Patr, JosAs; Philo, Congr. Erud. Gr. 1 = Gen 16:1 [PKatz, Philo’s Bible ’50, 36]; Jos., Ant. 18, 40; Ar. [Milne 74, 8]; Just., A I, 9, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.69\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:69</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.66\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:66</a>, 69; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:56</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:13</a>; 16:16, 19 D; GJs 2:2f. <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">θυρωρός</span>, «A escrava que guardava a porta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:17</a>. Com <span class=\"greek\">παῖς</span> (Lev 25:44; Dt 12:12, 18; TestAbr A 15 p. 95, 22 [Stone p. 38]; Pel-Leg. 12, 24f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:45</a>. Com <span class=\"greek\">δοῦλος</span> (2 Esdr 2:65; Eccl 2:7; Ar.; com <span class=\"greek\">δούλη</span> em JosAs 6:8), B 19:7; D 4:10; sobre as escravas de Deus (com <span class=\"greek\">δοῦλοι</span>, «escravos do sexo masculino»), 1 Cl 60:2. Em oposição específica a <span class=\"greek\">ἐλευθέρα</span>, com referência a Agar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:22f</a> (Gen 16:1ff; Philo, Leg. All. 3, 244); com uma inflexão para um sentido mais profundo, vv. 30ab (= Gen 21:10ab), 31.—JWackernagel, Glotta 2, 1909, 1–8; 218f; 315.—Lob., Phryn. 239f. Schmidt, Syn. II 429f. DELG s.v. <span class=\"greek\">παῖς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παιδόθεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παιδόθεν</span>, advérbio (Sb 5294, 8; Ps.-Lucian, Philopatr. 19; Themist., Or. 25 p. 310d; a prova de uso em Ibycus [VI a.C.] 1, 10 Bergk [= Diehl2 6, 12, variante textual], em Athen. 13, 601b, é questionável [o suplemento de L-S-J-M elimina a referência]; Sb 5294, 8 [III d.C.]), desde a infância: <span class=\"greek\">ἐκ</span> <span class=\"greek\">π</span>. (Laud. Therap. E, linha 8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:21</a>, variante textual. Ver <span class=\"greek\">παιδιόθεν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παιδοφθορέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παιδοφθορέω</span> (de <span class=\"greek\">παιδοφθόρος</span>: <span class=\"greek\">παῖς</span>, <span class=\"greek\">φθορέω</span>, «seduzir meninos»), futuro <span class=\"greek\">παιδοφθορήσω</span> (uso cristão: Just., D. 95, 1; Tat. 8, 1), praticar atividade sexual com um rapaz jovem do mesmo sexo, cometer sodomia, B 19:4; D 2:2.—Sobre a literatura antiga e moderna, ver PvanderHorst, The Sentences of Pseudo-Phocylides ’78, 250f; cf. 111; 237–39.—Ver DELG s.v. <span class=\"greek\">φθείρω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παιδοφθόρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παιδοφθόρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">παῖς</span>, <span class=\"greek\">φθόρος</span>, «sedutor de meninos»; cf. o verbete anterior; Physiogn. I 327, 16; TestLevi 17:11), pessoa que pratica sodomia com um menino, pederasta, B 10:6.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παίζω</span> (<span class=\"greek\">παῖς</span>), subjuntivo aoristo, 3.ª pessoa do singular <span class=\"greek\">παίξῃ</span>, Job 40:29; imperativo, 3.ª pessoa do singular e do plural <span class=\"greek\">παιξάτω</span>,-<span class=\"greek\">τωσαν</span>, LXX (Hom. e posteriores; Kaibel 362, 5; BGU 1024 VII, 26; PGM 7, 428; LXX; TestAbr A 10 p. 87, 23 [Stone p. 22]; EpArist 284; Philo; Jos., Bell. 4, 157; Tat. 8, 1; Ath. 31, 1), envolver-se em atividade com finalidade de diversão, brincar, divertir-se (Ion de Quios [V a.C.], Eleg. 1, 15f [= Campbell 26] <span class=\"greek\">καλῶν</span> <span class=\"greek\">ἐπιήρανε</span> <span class=\"greek\">ἔργων</span> | <span class=\"greek\">πίνειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παίζειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δίκαια</span> <span class=\"greek\">φρονεῖν</span> [dirigido a Dioniso], «Ó senhor de todos os feitos belos, concede-me longa vida de beber, divertir-me e pensar no que é justo»; 2, 7 Diehl3 [= Campbell 27] <span class=\"greek\">πίνωμεν</span>, <span class=\"greek\">παίζομεν</span>, «Bebamos, divirtamo-nos» [a dança integra a celebração, mas é expressa por outro verbo: <span class=\"greek\">ὀρχείσθω</span> <span class=\"greek\">τις</span>, linha 8]; Appian, Syr. 26, 125 <span class=\"greek\">παίζοντας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μεθύοντας</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:7</a> (Ex 32:6). <span class=\"greek\">π</span>. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>, «Brincar com alguém» (Gen 21:9; 26:8), Hs 9, 11, 4f.—DELG s.v. <span class=\"greek\">παῖς</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παῖς, παιδός, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino/feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παῖς</span>, <span class=\"greek\">παιδός</span>, <span class=\"greek\">ὁ</span> ou <span class=\"greek\">ἡ</span> (Hom. e outros), criança.<br>\n① Pessoa jovem normalmente abaixo da puberdade, com ênfase na idade, não na posição social, menino, jovem (Hom. e outros; inscrições, papiros, LXX; Philo, Op. M. 105; Jos., Ant. 12, 210; Just., D. 78, 2 e 7; ver VLeinieks, The City of Dionysos ’96, 199–210, sobre classes etárias), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:12</a>. <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">παῖς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:43</a>. Em referência a Jesus, GJs 20:4; 22:2.—No plural (como <span class=\"hebrew\" dir=\"rtl\">פְּדַיָּא</span>, empréstimo no hebraico rabínico), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:16</a>; 21:15; B 8:3f.—<span class=\"greek\">ἐκ</span> <span class=\"greek\">παιδός</span>, «Desde a infância» (Diod S 1, 54, 5; 1, 73, 9; 1, 92, 5; 19, 40, 2 e outros. Simplicius em Epict. p. 129, 26; UPZ 144, 19 [165 a.C.] <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">παιδὸς</span> <span class=\"greek\">φιλίας</span>; cf. Just., A I, 15, 6 <span class=\"greek\">ἐκ</span> <span class=\"greek\">παίδων</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:21</a> D.<br>\n② Descendente imediato de alguém, filho ou filha.<br>\nⓐ Sobre um filho, <span class=\"greek\">ὁ</span> <span class=\"greek\">παῖς</span> (Hom. e posteriores; Diod S 20, 22, 1 <span class=\"greek\">οἱ</span> <span class=\"greek\">παῖδες</span> <span class=\"greek\">αὐτοῦ</span>; inscrições, papiros, LXX; TestAbr A 7 p. 84, 19 [Stone p. 16]; JosAs 23:9; ApcMos 42; Jos., Bell. 4, 646, Ant. 20, 140 e outros; Just., A II, 2, 16 e outros; Tat. 41, 1; Mel., HE 4, 26, 7, P. 53, 389; Ath. 20, 2 e outros): <span class=\"greek\">ὁ</span> <span class=\"greek\">παῖς</span> <span class=\"greek\">αὐτοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:51</a> (= <span class=\"greek\">υἱός</span>, vv. 46f, 50; <span class=\"greek\">υἱός</span>, variante textual em lugar de <span class=\"greek\">παῖς</span> no v. 51). Essa acepção também é possível em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:6</a>, 8, 13, mas essas passagens provavelmente pertencem a 3a.<br>\nⓑ Sobre uma filha, <span class=\"greek\">ἡ</span> <span class=\"greek\">παῖς</span> (quanto ao termo feminino, que não se limita a «filha», ver Pind., Fgm. 107, 7 [122 Sch.] <span class=\"greek\">ὦ</span> <span class=\"greek\">παῖδες</span> = «meninas!»; Hyperid., Fgm. 144; Phalaris, Ep. 142, 1; Chariton 1, 8, 2; Philostrat., Her. 19, 11 p. 204, 31; Gen 24:28; 34:12; TestJob 7:7f; Jos., Ant. 1, 254; 5, 266 e outros; Tat. 8, 3; 33, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:51</a>; GJs, quinze vezes, referente a Maria. <span class=\"greek\">ἡ</span> <span class=\"greek\">παῖς</span>, «Minha filha» (nominativo com artigo pelo vocativo; ver B-D-F §147, 3; Rob. 465f; 769), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:54</a>.<br>\n③ Aquele que se encontra em completa obediência a outro, escravo, servo.<br>\nⓐ Sobre escravos e assistentes pessoais, escravo, servo (desde Hipponax [VI a.C.] 16 D.3; Aeschyl., Cho. 652. Também HUsener, Epicurea 1887 p. 168, 10; Plut., Alcib. 193 [4, 5], Mor. 65c; 70e; SIG 96, 26. Frequente em papiros e LXX; TestAbr B; JosAs 99:3 e outros; AscIs 3:5; Jos., Ant. 18, 192, Vi. 223.—Até mesmo um servo do sexo masculino particularmente confiável é chamado <span class=\"greek\">ὁ</span> <span class=\"greek\">παῖς</span>: Diod S 15, 87, 6, o escudeiro de Epaminondas; Appian, Iber. 27, 107, o cavalariço de Cipião; Gen 24:2ff, o principal servo de Abraão, v. 5 <span class=\"greek\">ὁ</span> <span class=\"greek\">παῖς</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:7</a> (= <span class=\"greek\">δοῦλος</span>, vv. 2f, 10); 15:26; AcPt Ox 849, 15 [Aa I 73, 21 Lat.]. Com <span class=\"greek\">παιδίσκη</span> (ver este verbete), 12:45. Provavelmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:6</a>, 8, 13 também pertence a esta acepção (ver 2a).—Acerca dos que servem na corte de um governante, <span class=\"greek\">οἱ</span> <span class=\"greek\">παῖδες</span>, «Cortesãos, assistentes» (Diod S 17, 36, 5; Gen 41:10, 37f; 1 Km 16:17; Jer 43:31; 44:2; 1 Macc 1:6, 8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:2</a>.<br>\nⓑ Sobre relações especiais.<br>\n<span class=\"greek\">α</span>. Seres humanos como servos ou escravos de Deus (Ael. Aristid. 45 p. 152 D.: <span class=\"greek\">θεῶν</span> <span class=\"greek\">παῖδες</span> [ou «filhos de deuses», como Polyb. 3, 47, 8; Chariton 2, 1, 5 e Diog. L. 9, 72]; LXX; ParJer 6:24 [Jeremias]). Israel (Is 41:8f; PsSol 12:6; 17:21), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:54</a>. Davi (Ps 17:1; Is 37:35), 1:69; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:25</a>; D 9:2a.—Sobre pessoas sem dolo: <span class=\"greek\">τοὺς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἀκακίαν</span> <span class=\"greek\">ἀσκοῦντας</span> <span class=\"greek\">παῖδας</span> <span class=\"greek\">ἐκάλουν</span>, <span class=\"greek\">ὡς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Παπίας</span> <span class=\"greek\">δηλοῖ</span>, «Como observa Pápias, os que levavam vida piedosa e sem dolo eram chamados crianças», Papias (8).<br>\n<span class=\"greek\">β</span>. Anjos como servos de Deus: Deus não confia em seus servos, 1 Cl 39:4 (Job 4:18). Sobre o jovem vindo do céu que libertou Paulo de suas correntes, <span class=\"greek\">παῖς</span> <span class=\"greek\">λείαν</span> (= <span class=\"greek\">λίαν</span>) <span class=\"greek\">εὐειδὴς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χάριτι</span>, AcPl Ha 3, 13f.<br>\n<span class=\"greek\">γ</span>. Sobre Cristo em sua relação com Deus. Nesse contexto, tem o sentido de servo por causa da identificação do «servo de Deus» de certas passagens do AT com o Messias (Is 52:13 e outros; BJanowski/PStuhlmacher, orgs., Der Leidende Gottesknecht ’96 [bibliografia]; DBS XII 1000–1016), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:18</a> (cf. Is 42:1); B 6:1; B 9:2 (sobre as duas últimas passagens, cf. Is 50:10). Assim, provavelmente também D 9:2b (pela proximidade imediata de <span class=\"greek\">Δαυὶδ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">παῖς</span> <span class=\"greek\">σου</span>, 9:2a); 9:3; 10:2f.—Em outras passagens (cf. Ath. 10, 2; 12, 2 e outras; Iren. 3, 12, 5 [Harv. II 58, 8]), o significado filho certamente deve ser preferido (<span class=\"greek\">παῖς</span> era compreendido assim no mundo grego quando expressava uma relação com uma divindade: Il. 2, 205 <span class=\"greek\">Κρόνου</span> <span class=\"greek\">παῖς</span>; Sappho 1, 2 Diehl; Alcaeus 1; Bacchylides 17, 70, Minos como <span class=\"greek\">παῖς</span> de Zeus; Hermocles [IV/III a.C.] p. 174 Coll. Alex. = Athen. 6, 63, 253d: Demétrio Poliorcetes como <span class=\"greek\">π</span>. <span class=\"greek\">Ποσειδῶνος</span> <span class=\"greek\">θεοῦ</span>; Diod S 17, 51, 1, o deus Amon manda seu profeta dirigir-se a Alexandre com <span class=\"greek\">χαῖρε</span>, <span class=\"greek\">ὦ</span> <span class=\"greek\">παῖ</span>; o que se segue deixa claro que se trata de geração; Plut., Mor. 180d; Maximus Tyr. 14, 1d; Paus. 2, 10, 3 <span class=\"greek\">Ἄρατος</span> <span class=\"greek\">Ἀσκληπιοῦ</span> <span class=\"greek\">π</span>.; Diogenes, Ep. 36, 1; Philostrat., Vi. Apoll. 7, 24 p. 279, 4; Porphyr., Vi. Plot. 23; Iambl., Vi. Pyth. 2, 10; IG IV2, 128, 50 [280 a.C.] e frequentemente; Sb 8314, 9, Hermes conduz o morto aos Campos Elísios <span class=\"greek\">ἅμα</span> <span class=\"greek\">παισὶ</span> <span class=\"greek\">θεῶν</span>. Ver acima b<span class=\"greek\">α</span> os <span class=\"greek\">παῖδες</span> <span class=\"greek\">θεῶν</span>. Cf. também Herm. Wr. 13, 2 <span class=\"greek\">ὁ</span> <span class=\"greek\">γεννώμενος</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">παῖς</span>; 13, 4; 14; Rtzst., Poim. 223f.—Celsus 7, 9): <span class=\"greek\">παῖς</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μονογενὴς</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">Χρ</span>., MPol 20:2. Deus como <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγαπητοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εὐλογητοῦ</span> <span class=\"greek\">παιδὸς</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">πατήρ</span>, 14:1. Correspondentemente, Cristo como <span class=\"greek\">ἀγαπητὸς</span> <span class=\"greek\">παῖς</span> de Deus, 14:3; Dg 8:11. O mesmo vale para as outras passagens de Dg: 8:9; 9:1.—Quanto às passagens restantes, dificilmente é possível decidir qual dos sentidos é preferível: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:13</a>, 26; 4:27, 30 (a menos que o <span class=\"greek\">παῖς</span> <span class=\"greek\">σου</span>, «teu servo», de 4:25 exija a mesma tradução nas demais passagens; JMénard, CBQ 19, ’57, 83–92 [Atos]); 1 Cl 59:2–4 (em jogo de palavras com <span class=\"greek\">παιδεύω</span>; mas aqui o termo <span class=\"greek\">ἠγαπημένος</span>, repetido nos vv. 2 e 3 [cf. os papiros mágicos de aproximadamente 300 d.C., em TSchermann, TU 34, 2b, 1909, 3: Cristo como <span class=\"greek\">ἠγαπημένος</span> <span class=\"greek\">παῖς</span>], poderia sugerir a tradução filho).—WBousset, Kyrios Christos2 1921, 56f; AvHarnack, Die Bezeichnung Jesu als ‘Knecht Gottes’ u. ihre Geschichte in d. alten Kirche: SBBerlAk 1926, 212–38; Jeremias, ZNW 34, ’35, 115–23; KEuler, D. Verkündigung v. leidenden Gottesknecht aus Jes 53 in d. griech. Bibel ’34; PSeidelin, D. ˓Ebed J. u. d. Messiasgestalt im Jesajatargum: ZNW 35, ’36, 194–231; HWolff, Jes 53 im Urchristent. ’502; EMcDowell, Son of Man and Suffering Servant ’44; ELohmeyer, Gottesknecht u. Davidssohn ’45, esp. 2–8; TNicklin, Gospel Gleanings ’50, 268f; OCullmann, Dieu Vivant 16, ’50, 17–34; HHegermann, Jes 53 in Field, Hexapla, Targum u. Peschitta ’54; ELohse, Märtyrer u. Gottesknecht ’55; WGrundmann, Sohn Gottes: ZNW 47, ’56, 113–33; OCullmann, Die Christologie des NT ’57; JPrice, Interpretation 12, ’58, 28–38 (Sinóticos); MHooker, Jesus and the Servant ’59; BvanIersel, ‘D. Sohn’ in d. synopt. Jesusworten, ’61, 52–65 (bibliografia); HOrlinsky, The So-called Suffering Servant in Isaiah 53, ’64 (ver resenha em CBQ 27, ’66, 147); EKränkl, Jesus der Knecht Gottes, ’72 (Atos); FDanker, Proclamation Comm.: Luke ’87, 82–86. WZimmerli/JJeremias, The Servant of God (tradução de HKnight), ’65 = Studies in Bibl. Theol. 20.—B. 87f. Schmidt, Syn. II 422–31. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παίω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παίω</span>, 1.º aoristo <span class=\"greek\">ἔπαισα</span> (Aeschyl., Hdt. e outros; papiros, LXX; PsSol 8:15; TestSol 2:12 D; Ath.; B-D-F §101 p. 55 s.v. <span class=\"greek\">τύπτειν</span>).<br>\n① Fazer contato violento por meio de um golpe com alguma coisa, golpear.<br>\nⓐ Com uma parte do corpo, bater, atingir, com acusativo da pessoa (Philostrat., Vi. Soph. 2, 10, 6; PSI 168, 15 [II a.C.] <span class=\"greek\">ἔπαισάν</span> <span class=\"greek\">με</span>; 2 Km 14:6; Jos., Bell. 2, 176), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.68\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:68</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.64\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:64</a>.<br>\nⓑ Com instrumentos cortantes, golpear, ferir, com acusativo da pessoa (X., Cyr. 8, 5, 12; Diod S 11, 69, 5 <span class=\"greek\">παίει</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ξίφει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἀρταξέρξην</span>; 2 Km 20:10; TestJud 9:3 (Ch.); Jos., Ant. 4, 153), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:10</a>.<br>\nⓒ Com ferrão, picar, acerca de escorpiões (Aelian, NA 10, 23; Ael. Dion. <span class=\"greek\">ε</span>, 8), com acusativo da pessoa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:5</a>.<br>\n② Infligir punição, golpear, extensão figurada de 1 (em citações de Jó em 1 Cl): <span class=\"greek\">ἔπαισεν</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">σητὸς</span> <span class=\"greek\">τρόπον</span>, 1 Cl 39:5 (Job 4:19). Em uso absoluto: <span class=\"greek\">ἔπαισεν</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">χεῖρες</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἰάσαντο</span>, 56:7 (Job 5:18).—B. 553. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πακατιανός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πακατιανός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span>, pacatiano, «da Pacácia», denominação posterior (pós-Constantino) de uma parte da Frígia, empregada na subscrição de 1 Ti, variante textual (também se atestam outras formas do vocábulo). A capital desse distrito era Laodiceia, onde, segundo a subscrição, 1 Ti foi escrita.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάλαι</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάλαι</span>, advérbio de tempo passado, em contraste com o presente (Hom. e outros; inscrições, papiros, LXX; Just.; Tat. 6, 2, Ant. 4, 153).<br>\n① Relativo a um momento do passado, há muito tempo, outrora, antigamente (Philo, Sacr. Abel. 134 <span class=\"greek\">πάλαι</span>, <span class=\"greek\">νῦν</span>, <span class=\"greek\">αὖθις</span>, <span class=\"greek\">ἀεί</span>; Jos., Ant. 16, 40 e Just., A I, 14, 2 <span class=\"greek\">π</span>. … <span class=\"greek\">νῦν</span>): <span class=\"greek\">πάλαι</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">μετενόησαν</span>, «Há muito tempo teriam se arrependido», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:1</a>. <span class=\"greek\">ταῦτα</span> <span class=\"greek\">πάλαι</span> <span class=\"greek\">ἠκούσαμεν</span>, «Ouvimos essas coisas há muito tempo», 2 Cl 11:2 (citação profética de origem desconhecida). <span class=\"greek\">ἐκεῖνοι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἠρνημένοι</span>, «Aqueles que negaram no passado», Hs 9, 26, 6. <span class=\"greek\">ἄνθρωποι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">προγεγραμμένοι</span>, Jd 4 (também é possível a acepção 2). <span class=\"greek\">αἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἁμαρτίαι</span>, «Os pecados de outrora, pecados cometidos no passado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:9</a> (cf. Appian, Bell. Civ. 4, 124 §521 <span class=\"greek\">ὁ</span> <span class=\"greek\">πάλαι</span> <span class=\"greek\">Καῖσαρ</span>; BGU 747, 9 [II d.C.] <span class=\"greek\">οἱ</span> <span class=\"greek\">πάλαι</span> <span class=\"greek\">στρατιῶται</span>). <span class=\"greek\">οἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">θεῖοι</span> <span class=\"greek\">ἄγγελοι</span>, «Os anjos que originalmente eram santos», Papias (4).<br>\n② Relativo a um período relativamente longo, olhando-se do presente para algum ponto anterior, há muito tempo, desde muito tempo (Pla., Phd. 8, 63d; Esth 3:13g; Jos., Ant. 11, 32, Vi. 226; Just., D. 13, 1; 51, 3): <span class=\"greek\">πάλαι</span> <span class=\"greek\">δοκεῖτε</span>, «Há muito tempo pensais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:19</a> (variante textual <span class=\"greek\">πάλιν</span>). Talvez Jd 4 (ver 1 acima) e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:47</a>, variante textual (ver 3 abaixo).<br>\n③ Relativo a um momento dentro de um período relativamente curto anterior ao presente (um pouco mais longo que o indicado pelo emprego de <span class=\"greek\">ἤδη</span>, ver este verbete), já (Appian, Syr. 66, 348): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:47</a>, variante textual (remete ao momento da partida.—Também é provável a acepção 2). <span class=\"greek\">εἰ</span> <span class=\"greek\">πάλαι</span> <span class=\"greek\">ἀπέθανεν</span> (refere-se ao momento da crucificação), «Se já estava morto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:44</a> (variante textual <span class=\"greek\">ἤδη</span>).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παλαιός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παλαιός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">πάλαι</span>; Hom. e posteriores; empréstimo no hebraico rabínico), frequentemente com conotação de antiquado ou gasto (assim Soph., Oed. R. 290; Lysias, Fgm. 6 Thalh.; Diod S 3, 46, 4). Comparativo <span class=\"greek\">παλαιότερος</span> (LXX, Just., Tat.). Superlativo <span class=\"greek\">παλαίτατος</span> (Tat.).<br>\n① Relativo àquilo que existe há muito tempo, velho, antigo: PtK 2 p. 15, 7. <span class=\"greek\">μυθεύματα</span>, IMg 8:1. <span class=\"greek\">βασιλεία</span>, IEph 19:3. <span class=\"greek\">διαθήκη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:14</a> (= de muito tempo atrás; ver <span class=\"greek\">διαθήκη</span> 2). <span class=\"greek\">ἐντολὴ</span> (<span class=\"greek\">ἡ</span>) <span class=\"greek\">π</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:7</a>ab (cf. Pla., Leg. 1, 636b <span class=\"greek\">π</span>. <span class=\"greek\">νόμιμον</span>; 2, 659b, Lys. 6, 51; PGiss 4, 9 [118 d.C.] <span class=\"greek\">παλαιὸν</span> <span class=\"greek\">πρόσταγμα</span>; Just., D. 11, 2 <span class=\"greek\">νόμος</span>). <span class=\"greek\">οἶνος</span> (em oposição a <span class=\"greek\">νέος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:39</a>ab (Od. 2, 340; Diod S 2, 14, 4; Lucian, De Merc. Cond. 26; PSI 191, 2; 193, 3; JosAs 15:14 [p. 62, 19 Bat. e Pal. 364]). <span class=\"greek\">ἱμάτιον</span> (TestZeb 4:10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:21a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:36a</a>; com <span class=\"greek\">ἱμάτιον</span> subentendido, ibid. v. 36b. <span class=\"greek\">ἀσκοί</span> (Josh 9:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:37</a> (HImmerwahr, New Wine in Ancient Wineskins, The Evidence fr. Attic Vases: Hesperia 61, ’92, 121–32). Sobre uma rocha antiga, interpretada como Cristo em Hermas, Hs 9, 2, 2; 9, 12, 1. Sobre o próprio <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, 9, 12, 2. Sobre o Logos: <span class=\"greek\">οὗτος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἀρχῆς</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">καινὸς</span> <span class=\"greek\">φανεὶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παλαιὸς</span> <span class=\"greek\">εὑρεθεὶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάντοτε</span> <span class=\"greek\">νέος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁγίων</span> <span class=\"greek\">καρδίαις</span> <span class=\"greek\">γεννώμενος</span>, Dg 11:4 (<span class=\"greek\">καινός</span> e <span class=\"greek\">π</span>. contrapostos, como Hdt. 9, 26. Ver também Mel., P. 2, 8 e outros).—Substantivado (Hippocr., Ep. 12, 5; ApcEsdr 5:5): <span class=\"greek\">τὸ</span> <span class=\"greek\">καινὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παλαιοῦ</span>, «O novo do velho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:21b</a>. <span class=\"greek\">παλαιά</span> (em oposição a <span class=\"greek\">καινά</span>: Hdt. 9, 27 <span class=\"greek\">παλαιὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">καινὰ</span> <span class=\"greek\">λέγειν</span>; Socrat., Ep. 28 [30], 9; Procop. Soph., Ep. 122 <span class=\"greek\">μίγνυσι</span> <span class=\"greek\">παλαιὰ</span> <span class=\"greek\">καινοῖς</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:52</a>.<br>\n② Relativo àquilo que se tornou obsoleto ou inferior devido à antiguidade, velho, obsoleto, figuradamente: <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἄνθρωπος</span>, «O velho (isto é, anterior, não regenerado) homem ou eu» (<span class=\"greek\">ἄνθρωπος</span> 5b), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:9</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">ζύμη</span>, «O fermento velho» (ver <span class=\"greek\">ζύμη</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:7f</a> (em oposição a <span class=\"greek\">νέον</span> <span class=\"greek\">φύραμα</span>). <span class=\"greek\">π</span>. <span class=\"greek\">πράγματα</span>, «Modos de vida obsoletos (isto é, judaicos)» (<span class=\"greek\">παλ</span>. <span class=\"greek\">πράγματα</span> frequentemente em Vett. Val.; ver índice), IMg 9:1 (em oposição a <span class=\"greek\">καινότης</span> <span class=\"greek\">ἐλπίδος</span>).—OLinton, ‘Gammalt’ och ‘nytt’: Svensk Ex. Årsbok 5, ’40, 43–55.—B. 958. DELG s.v. <span class=\"greek\">πάλαι</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παλαιότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παλαιότης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παλαιός</span>; Eur., Aeschin., Pla. e outros), condição de ter sido superado ou tornado obsoleto, antiguidade, obsolescência: <span class=\"greek\">δουλεύειν</span> … <span class=\"greek\">παλαιότητι</span> <span class=\"greek\">γράμματος</span>, «Servir à letra obsoleta (da lei; em oposição a <span class=\"greek\">καινότης</span> <span class=\"greek\">πνεύματος</span>)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:6</a>.—DELG s.v. <span class=\"greek\">πάλαι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παλαιόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παλαιόω</span> (<span class=\"greek\">παλαιός</span>), futuro, 3.ª pessoa singular <span class=\"greek\">παλαιώσει</span>, Da 7:25 Theod.; aoristo, 3.ª pessoa singular <span class=\"greek\">ἐπαλαίωσεν</span>; perfeito <span class=\"greek\">πεπαλαίωκα</span>. Passiva: 1.º futuro <span class=\"greek\">παλαιωθήσομαι</span>, LXX; 1.º aoristo <span class=\"greek\">ἐπαλαιώθην</span>; perfeito <span class=\"greek\">πεπαλαίωμαι</span>, LXX (Pla. e outros; papiros, LXX; En; Ath., R. 9 p. 7, 26; fora da Bíblia, somente na passiva).<br>\n① Ativa (La 3:4; Is 65:22; Da 7:25 Theod.), envelhecer, tornar velho, declarar ou tratar como obsoleto: <span class=\"greek\">τὴν</span> <span class=\"greek\">πρώτην</span> (isto é, <span class=\"greek\">διαθήκην</span>), «Tratar a primeira aliança como obsoleta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:13a</a>.<br>\n② Passiva, tornar-se velho (frequentemente com conotação de tornar-se inútil: Pla., Symp. 208b; Diog. L. 7, 159; Sb 5827, 11 [69 a.C.]; APF 2, 1903, 441 n.º 55, 4 <span class=\"greek\">τείχη</span> <span class=\"greek\">παλαιωθέντα</span>, «Muros que se tornaram ruinosos»; LXX; En 104, 2; Philo, Sobr. 56; Ath., R. 9 p. 57, 26): <span class=\"greek\">βαλλάντια</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">παλαιούμενα</span>, «Bolsas que não se gastam», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:33</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">ἱμάτιον</span> <span class=\"greek\">παλαιοῦσθαι</span> (Dt 29:4; Josh 9:5; 2 Esdr 19:21; Sir 14:17; Is 51:6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:11</a> (Ps 101:27); B 6:2 (Is 50:9). <span class=\"greek\">ζύμη</span> <span class=\"greek\">παλαιωθεῖσα</span>, «Fermento que se tornou velho» (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:7</a>), IMg 10:2. <span class=\"greek\">παλαιοῦσθαι</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">λύπαις</span>, «Envelhecer por causa das tristezas», Hv 3, 11, 3. <span class=\"greek\">τὸ</span> <span class=\"greek\">παλαιούμενον</span> (com <span class=\"greek\">γηράσκον</span>), «Aquilo que se tornou obsoleto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:13b</a> (inscrição [218 a.C.]: <span class=\"greek\">ΕΛΛΗΝΙΚΑ</span> 7, ’34 p. 179, 14 <span class=\"greek\">παλαιούμενα</span> = coisas tornadas inúteis).—DELG s.v. <span class=\"greek\">πάλαι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παλαίω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παλαίω</span>, 1.º aoristo <span class=\"greek\">ἐπάλαισα</span> (Hom. e outros; LXX; TestAbr A 10 p. 87, 24 [Stone p. 22]; Demetr.: 722 Fgm. 1, 7 Jac.; Philo; Jos., B. 1, 657; Just., Tat.), lutar corpo a corpo, lutar, com <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>, «com alguém» (Gen 32:25f; Just., D. 125, 3): <span class=\"greek\">οἱ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span> <span class=\"greek\">παλαίσαντες</span>, «Aqueles que lutaram contra o diabo», Hs 8, 3, 6.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάλη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάλη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παλαίω</span>, «lutar corpo a corpo»; Hom. e outros; inscrições; Sb 678, 6), participação numa competição difícil (originalmente, «luta corpo a corpo», Il. 23, 635 e outros, depois, confrontos ou batalhas, Aeschyl., Ch. 866; Eur., Heracl. 159), luta contra, extensão figurada (Longus 3, 19, 2, sobre o amor; Philo, Sobr. 65 <span class=\"greek\">πρὸς</span> <span class=\"greek\">πάθη</span> <span class=\"greek\">π</span>., aqui com imagem da luta), sobre o combate dos cristãos contra os poderes das trevas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:12</a> (o adversário é introduzido por <span class=\"greek\">πρός</span> com acusativo, como em Philo acima, mas o contexto sugere imagética militar).—DELG s.v. <span class=\"greek\">παλαίω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παλιγγενεσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παλιγγενεσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Plut., Mor. 722d não atribui, como alguns afirmaram, o uso da palavra a Demócrito [Fgm. 158 Diels]; ocorre em Neanthes [200 a.C.]: 84 Fgm. 33 Jac.; Memnon [I a.C./I d.C.]: 434 Fgm. 1, 40, 2 Jac.; Cicero, Ad Attic. 6, 6, também como termo técnico dos pitagóricos e estoicos [EZeller, Philosophie der Griechen I5 1892, 442; III 14 1902, 158; HDiels, Doxographi Graeci 1879, p. 469, 11ff], assim como dos mistérios de Dioniso [Orph. Fragmente 205 p. 225 OKern 1922] e de Osíris [Plut., Mor. 389a; também 364f; 379f; 438d; 996c; 998c; cf. Lucian, Musc. Enc. 7]. Aparece em Herm. Wr. [3, 3; 13, 1 <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παλιγγενεσίας</span> <span class=\"greek\">λόγος</span>; 13, 3 e outros.—JKroll, Die Lehren des Hermes Trismegistos 1914, 360ff; Prümm 559–61]; IDefixWünsch 4, 18 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παλινγενεσίας</span> <span class=\"greek\">Θωβαρραβαυ</span>; PLond 878 <span class=\"greek\">δῶρον</span> <span class=\"greek\">παλινγενεσίας</span>; Philo, Cher. 114, Poster. Caini 124, Leg. ad Gai. 325; Jos., Ant. 11, 66).<br>\n① Estado de renovação, com ênfase numa experiência cósmica, renovação.<br>\nⓐ Depois do Dilúvio (assim Philo, Mos. 2, 65, mas a ideia de <span class=\"greek\">παλιγγενεσία</span> do <span class=\"greek\">κόσμος</span> é geralmente estoica e originou-se entre os pitagóricos: M. Ant. 11, 1, 3; Philo, Aet. M. 47; 76): <span class=\"greek\">Νῶε</span> <span class=\"greek\">παλ</span>. <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">ἐκήρυξεν</span>, 1 Cl 9:4.<br>\nⓑ Sobre a renovação do mundo na época do Messias, em sentido escatológico (Schürer II 537f; Bousset, Rel.3 280ff): <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">παλ</span>., «Na nova era ou no novo mundo (messiânico)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28</a>.<br>\n② Experiência de transformação completa da vida, renascimento de uma pessoa redimida (cf. Heraclit., Ep. 4, 4 <span class=\"greek\">ἐκ</span> <span class=\"greek\">παλιγγενεσίας</span> <span class=\"greek\">ἀναβιῶναι</span>; Herm. Wr., loc. cit. e PGM 4, 718, em que o iniciado se denomina <span class=\"greek\">πάλιν</span> <span class=\"greek\">γενόμενος</span>. Theoph. Ant. 2, 16 [p. 140, 9] <span class=\"greek\">λαμβάνειν</span> … <span class=\"greek\">ἄφεσιν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">ὕδατο</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λουτροῦ</span> <span class=\"greek\">παλιγγενεσία</span>): <span class=\"greek\">λουτρὸν</span> <span class=\"greek\">παλιγγενεσίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνακαινώσεως</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span>, «Banho de regeneração e renovação pelo Espírito Santo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:5</a> (MDibelius, Hdb., excursus ad loc.; ESelwyn, I Pt ’46, 306f; ANock, JBL 52, ’33, 132f).—PGennrich, Die Lehre v. d. Wiedergeburt in dogmengeschichtl. und religionsgeschichtl. Beleuchtung 1907; AvHarnack, Die Terminologie der Wiedergeburt: TU 42, 3, 1918, p. 97–143; ADieterich, Eine Mithrasliturgie 1903, 157ff; Rtzst., Mysterienrel.3, índices; HWilloughby, Pagan Regeneration 1929; VJacono, La <span class=\"greek\">παλιγγενεσία</span> in S. Paolo e nel ambiente pagano: Biblica 15, ’34, 369–98; JDey, <span class=\"greek\">Παλιγγενεσία</span> (sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:5</a>) ’37; JYsebaert, Gk. Baptismal Terminology, ’62, 90; FBurnett, CBQ 46, ’84, 447–70 (Philo, renascimento da alma em existência incorpórea).—Kl. Pauly IV 428f; BHHW III 2171f.—Ver DELG s.v. <span class=\"greek\">πάλιν</span>. M-M s.v. <span class=\"greek\">παλινγενεσία</span>. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάλιν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάλιν</span>, advérbio (Hom. e posteriores). Sobre a grafia, ver B-D-F §20, final; Mlt-H. 113).<br>\n① Relativo ao retorno a uma posição ou condição, de volta.<br>\nⓐ Com verbos de ir, enviar, virar, chamar etc.: <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἄγειν</span>, «Voltar, retornar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:7</a>. <span class=\"greek\">ἀναβαίνειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:1</a>. <span class=\"greek\">ἀναχωρεῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:15</a>. <span class=\"greek\">ἀποστέλλειν</span>, «Enviar de volta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:3</a>. <span class=\"greek\">διαπερᾶν</span>, 5:21. <span class=\"greek\">ἔρχεσθαι</span> (Jos., Ant. 2, 106; 11, 243), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.46\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:16</a>. <span class=\"greek\">ἀπέρχεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:3</a>. <span class=\"greek\">εἰσέρχεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:1</a> (ParJer 7:22). <span class=\"greek\">ἐξέρχεσθαι</span>, 7:31 (ParJer 9:12). <span class=\"greek\">ἐπιστρέφειν</span>, «Voltar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:9a</a>. <span class=\"greek\">παραγίνεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:2</a> etc. <span class=\"greek\">πάλιν</span> <span class=\"greek\">λαβεῖν</span>, «Retomar, receber de volta» (X., An. 4, 2, 13), 10:17f. <span class=\"greek\">παραλαβὼν</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">δώδεκα</span>, «Tornou a levar consigo os Doze» (depois de ter estado separado deles por algum tempo e caminhado à frente), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:32</a>. <span class=\"greek\">ἀνεσπάσθη</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἅπαντα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανόν</span>, «Tudo foi puxado de volta ao céu», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:10</a>.—<span class=\"greek\">ἡ</span> <span class=\"greek\">ἐμὴ</span> <span class=\"greek\">παρουσία</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span>, «Meu retorno a vós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:26</a>.—Também pleonasticamente com verbos que já exprimem o componente «de volta» (Eur., Ep. 1, 1 <span class=\"greek\">ἀναπέμπω</span> <span class=\"greek\">πάλιν</span>): <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἀνακάμπτειν</span> (Bacchylides 17, 81f <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἀνεκάμπτετ</span>’; Synes., Kingship p. 29b), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:21</a>. <span class=\"greek\">πάλιν</span> <span class=\"greek\">ὑποστρέφειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:17</a> (ver B-D-F §484; cf. Rob. 1205).<br>\nⓑ Em expressões que indicam regresso a uma condição anterior ou retomada de uma atividade anterior (TestAbr A 6 p. 89, 13 [Stone p. 14] <span class=\"greek\">ἠγέρθη</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μόσχος</span>; ApcMos 41 <span class=\"greek\">πάλιν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀνάστασιν</span> <span class=\"greek\">ἐπαγγέλομαί</span> <span class=\"greek\">σοι</span>; Just., A I, 18, 6; Tat. 11, 2). Em inglês, geralmente «again», em português, novamente. <span class=\"greek\">εἰ</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">κατέλυσα</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">οἰκοδομῶ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:18</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">ἦτε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a>. <span class=\"greek\">διψήσει</span> <span class=\"greek\">πάλιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:13</a>. <span class=\"greek\">πάλιν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φόβον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:15</a>. Cf. 11:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:12</a>; 6:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:20</a>.<br>\n② Relativo à repetição da mesma maneira (ou de modo semelhante), de novo, outra vez, novamente, acerca de algo que uma pessoa já fez (TestAbr A 15 p. 96, 7 [Stone p. 40, 7]; TestJob 15:9; 44:2; JosAs 10:19; ParJer 9:21; Jos., Ant. 12, 109; Just., D. 3, 5 e outros), de um acontecimento ou de uma condição ou circunstância (Dicaearch., Fgm. 34 W. Pitágoras foge primeiro para <span class=\"greek\">Καυλωνία</span> … <span class=\"greek\">ἐκεῖθεν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Λοκρούς</span>; ApcEsdr 4:13 <span class=\"greek\">κατήγαγόν</span> <span class=\"greek\">με</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">κατήγαγόν</span> <span class=\"greek\">με</span> <span class=\"greek\">βαθμοὺς</span> <span class=\"greek\">τριάκοντα</span>). <span class=\"greek\">πάλιν</span> <span class=\"greek\">παραλαμβάνει</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">διάβολος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὄρος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:8</a> (cf. v. 5). <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἐξελθών</span>, 20:5 (cf. v. 3). <span class=\"greek\">πότε</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">ὄψονται</span> <span class=\"greek\">αὐτόν</span>, «Quando voltariam a vê-lo (Paulo)», AcPl Ha 6, 17. <span class=\"greek\">ἵνα</span> <span class=\"greek\">παρά</span> <span class=\"greek\">σου</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἀκούσωμεν</span>, AcPlCor 1:6.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:36</a> (cf. v. 34); 26:44 (cf. v. 42), 72; 27:50; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:13</a>; 3:1; 4:1. <span class=\"greek\">πάλιν</span> <span class=\"greek\">πολλοῦ</span> <span class=\"greek\">ὄχλου</span> <span class=\"greek\">ὄντος</span>, 8:1 (cf. 6:34).—8:25; 10:1, 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:20</a> (cf. v. 13); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:35</a> (cf. v. 29); 8:8; 20:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:18</a>; Hv 3, 1, 5 e outros; GJs 17:2; 23:2; AcPl Ha 4, 1.—Por vezes com acréscimos que, em parte, especificam <span class=\"greek\">πάλιν</span>: <span class=\"greek\">πάλ</span>. <span class=\"greek\">δεύτερον</span> (cf. P. Argentor. Gr. 53, 5: Kl. T. 135 p. 47 <span class=\"greek\">τὸ</span> <span class=\"greek\">δεύτερον</span> <span class=\"greek\">πάλιν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:16</a>. <span class=\"greek\">πάλ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">δευτέρου</span> (Ctesias: 688 Fgm. 14, 31 Jac.; 4 [6] Esdr [POxy 1010]; PCairMasp 24, 12), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:15</a>. Também pleonasticamente <span class=\"greek\">πάλ</span>. <span class=\"greek\">ἄνωθεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:9b</a> (ver <span class=\"greek\">ἄνωθεν</span> 4). <span class=\"greek\">αὖ</span> <span class=\"greek\">πάλιν</span>, Papias (2:9) (cf. Just., A I, 20, 2). <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀρχῆς</span> (Mnesimachus Com. [IV a.C.] 4, 24; Diod S 17, 37, 5), B 16:8.—<span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πάλιν</span> = <span class=\"greek\">πάλιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:2</a> (sobre isso, ver WSchmid, Der Attizismus 1887–97, I 167; II 129; III 282; IV 455; 625).<br>\n③ Marcador de um elemento do discurso ou da narrativa acrescentado a elementos correlatos, também, novamente, além disso, em seguida (Ps.-Pla., Eryx. 11, 397a <span class=\"greek\">καὶ</span> <span class=\"greek\">π</span>., numa série de exemplos); muito frequente numa sequência de citações das Escrituras (cf. Diod S 37, 30, 2 <span class=\"greek\">καὶ</span> <span class=\"greek\">πάλιν</span> … <span class=\"greek\">καὶ</span> …, nas duas vezes seguido por uma citação poética; uma terceira já as precedera. As três tratam da riqueza como bem supremo e provavelmente provêm de uma coleção de citações; Ps.-Demetr. c. 184 <span class=\"greek\">καὶ</span> <span class=\"greek\">πάλιν</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">π</span>., com uma citação em cada caso. Cf. também Diod S 1, 96, 6; Diog. L. 2, 18; 3, 16; Athen. 4, 17, 140c; 14, 634d; Plut., Mor. 361a <span class=\"greek\">καὶ</span> <span class=\"greek\">πάλιν</span> … <span class=\"greek\">καὶ</span> …; em ambos os casos segue-se uma citação; Just., A I, 35, 5; 38, 2 e outros; Ath. 9, 1 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:39</a>; 19:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:10</a>–12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:5</a>; 2:13ab; 4:5; 10:30; 1 Cl 10:4; 15:3f; 16:15; 17:6; 26:3; B 2:7; B 3:1; B 6:2, B 4, B 6, B 14, B 16 e frequentemente. Numa série de parábolas (Simplicius, In Epict. p. 111, 13–34, liga por meio de <span class=\"greek\">π</span>. duas narrativas semelhantes às do bom samaritano e do fariseu e publicano; Kephal. I 76, 34; 77, 8 [série de provérbios]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:20</a> (cf. v. 18). Também expressão preferida quando o orador retoma e desenvolve uma fórmula anteriormente empregada: <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἠκούσατε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:33</a> (cf. v. 27). <span class=\"greek\">πάλιν</span> <span class=\"greek\">ὁμοία</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">βασιλεία</span>, 13:45 (cf. v. 44), 47.—18:19 (cf. v. 18); 19:24 (cf. v. 23).<br>\n④ Marcador de contraste ou de aspecto alternativo, por outro lado, por sua vez (Pla., Gorg. 482d; Theocr. 12, 14; Polyb. 10, 9, 1; Diod S 4, 46, 3; Chariton 7, 6, 9; Wsd 13:8; 16:23; 2 Macc 15:39; TestJob 26:4; GrBar 4:15; Just., D. 41, 4 e outros): <span class=\"greek\">πάλιν</span> <span class=\"greek\">γέγραπται</span>, «Por outro lado, está escrito», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:7</a>. <span class=\"greek\">πάλ</span>. <span class=\"greek\">Ἀνδρέας</span>, «André, por sua vez», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:22</a>, variante textual.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:21</a>. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">λογιζέσθω</span> <span class=\"greek\">πάλ</span>. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἐαυτοῦ</span>, «Que ele, por outro lado, lembre a si mesmo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:7</a>; «por outro lado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:8</a>.<br>\n⑤ Uma dificuldade especial é apresentada por <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:13</a>, no qual o primeiro clamor da multidão é relatado com as palavras <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἔκραξεν</span>. Seria simplesmente um conectivo (como <span class=\"greek\">δὲ</span> <span class=\"greek\">πάλιν</span> em Ps.-Callisth. 2, 21, 22; POxy 1676, 20 <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λυποῦμαι</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐκτός</span> <span class=\"greek\">μου</span> <span class=\"greek\">εἶ</span>)? Dever-se-ia isso ao emprego de outra fonte nesse ponto? Ou o sentido seria «Eles gritaram em resposta» (assim Goodsp.; ver 1a)? Ou trata-se realmente de um segundo clamor, com o primeiro oculto por trás dos vv. 8 ou 11? De acordo com o paralelo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:21f</a>, que de fato menciona vários clamores sucessivos, o primeiro talvez fosse <span class=\"greek\">τὸν</span> <span class=\"greek\">Βαραββᾶν</span>. O <span class=\"greek\">πάλιν</span> de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:40</a> também é difícil de explicar (Bultmann 502; 509, 3). Haveria alguma conexão entre Marcos e João nesse ponto?—Outra possibilidade seria classificar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:13</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:40</a> na acepção 4 acima, com o sentido «por sua vez» (Aristoph., Acharn. 342 e outros; ver L-S-J-M). Sobre um possível pano de fundo aramaico, ver JHudson, ET 53, ’41/42, 267f; Mlt-H. 446; Mlt-Turner 229; MBlack, An Aramaic Approach3, ’67, 112f.—B. 989. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παλινγενεσία</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παλινγενεσία</span>: ver <span class=\"greek\">παλιγγενεσία</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παλίουρος</h1><div class=\"entry-meta\"><span>substantivo masculino/feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παλίουρος</span>, <span class=\"greek\">οὐ</span>, <span class=\"greek\">ὁ</span> e <span class=\"greek\">ἡ</span> (Eur., Cyclops 394; Theopomp.: 115 Fgm. 133 Jac. [= Hell. Oxy. 129 G-H.]; Theophrast., HP 1, 3, 2; 4, 3, 3 e outros; BGU 1120, 16 [I a.C.]), sarça, espinheiro, matagal, AcPl Ha 4, 25 (reconstituição em contexto fragmentário).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0265-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παμβότανον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παμβότανον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">πᾶς</span>, <span class=\"greek\">βοτάνη</span>), vegetação que cobre toda uma área, vegetação que recobre tudo: <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγροῦ</span>, «Vegetação que cobre todo o campo», 1 Cl 56:14 (Job 5:25). A imagem é a de um campo recoberto em todas as direções por vegetação tão densa que não se pode contar cada planta separadamente. Tão numerosos serão os descendentes de Jó. Outros interpretam como «todas as plantas do campo».—DELG s.v. <span class=\"greek\">βόσκω</span>.</p></section></article>"};
